/* ==========================================================================
   PatchPad Incident Report Editor - Theme & Styles
   Clean, modern, readable typography, high-contrast & desktop optimized (1280x800)
   ========================================================================== */

:root {
  --bg-app: #0f172a;
  --bg-panel: #1e293b;
  --bg-surface: #334155;
  --bg-surface-hover: #475569;
  --bg-input: #0f172a;
  --border-color: #334155;
  --border-focus: #38bdf8;

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  --accent-primary: #38bdf8;
  --accent-primary-hover: #0ea5e9;
  --accent-primary-text: #0f172a;

  --color-success: #10b981;
  --color-success-bg: rgba(16, 185, 129, 0.15);
  --color-warning: #f59e0b;
  --color-warning-bg: rgba(245, 158, 11, 0.15);
  --color-danger: #ef4444;
  --color-danger-bg: rgba(239, 68, 68, 0.15);

  --editor-bg: #0b0f19;
  --editor-gutter-bg: #090d16;
  --editor-gutter-text: #475569;
  --editor-gutter-active: #94a3b8;
  --editor-text: #e2e8f0;
  --editor-selection: rgba(56, 189, 248, 0.28);
  --editor-caret: #38bdf8;
  --editor-caret-sec: #a855f7;
  --editor-find-match: rgba(234, 179, 8, 0.35);
  --editor-find-active: rgba(249, 115, 22, 0.6);

  --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'SF Mono', Consolas, Menlo, Monaco, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-app);
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* ----------------------------------------------------
   Main Layout Structure
   ---------------------------------------------------- */
#app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

/* ----------------------------------------------------
   Top Header & Metadata Bar
   ---------------------------------------------------- */
.header-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  background-color: var(--bg-panel);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  gap: 16px;
  flex-wrap: wrap;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.app-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 16px;
  color: var(--accent-primary);
  letter-spacing: -0.02em;
}

.brand-icon {
  width: 24px;
  height: 24px;
  fill: currentColor;
}

.doc-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.doc-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.doc-meta {
  font-size: 12px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.doc-meta-item::after {
  content: "•";
  margin-left: 8px;
  color: var(--text-muted);
}
.doc-meta-item:last-child::after {
  content: "";
}

.header-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

/* Status Badges */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}

.badge-saved {
  background-color: var(--color-success-bg);
  color: var(--color-success);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.badge-unsaved {
  background-color: var(--color-warning-bg);
  color: var(--color-warning);
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.badge-revision {
  background-color: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  font-family: var(--font-mono);
}

.badge-cursor {
  background-color: var(--bg-surface);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  font-family: var(--font-mono);
}

/* ----------------------------------------------------
   Toolbar Controls
   ---------------------------------------------------- */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 18px;
  background-color: #141f33;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  gap: 10px;
  flex-wrap: wrap;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 12px;
  background-color: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.btn:hover:not(:disabled) {
  background-color: var(--bg-surface-hover);
  border-color: var(--text-muted);
}

.btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-primary {
  background-color: var(--accent-primary);
  color: var(--accent-primary-text);
  border-color: var(--accent-primary);
  font-weight: 600;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--accent-primary-hover);
  border-color: var(--accent-primary-hover);
}

.btn-icon-only {
  padding: 6px 8px;
}

.btn svg {
  width: 15px;
  height: 15px;
  fill: currentColor;
}

.btn .shortcut-hint {
  font-size: 11px;
  opacity: 0.65;
  font-family: var(--font-mono);
  margin-left: 2px;
}

.select-report {
  background-color: var(--bg-input);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
}

.select-report:focus {
  outline: 2px solid var(--border-focus);
}

/* ----------------------------------------------------
   Find & Replace Bar
   ---------------------------------------------------- */
.find-replace-bar {
  display: flex;
  align-items: center;
  padding: 8px 18px;
  background-color: #1a2436;
  border-bottom: 1px solid var(--border-color);
  gap: 12px;
  flex-shrink: 0;
  flex-wrap: wrap;
  transition: all 0.2s ease;
}

.find-replace-bar.hidden {
  display: none;
}

.find-field-group {
  display: flex;
  align-items: center;
  gap: 6px;
  background-color: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 2px 6px;
}

.find-field-group:focus-within {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 1px var(--border-focus);
}

.find-input {
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 13px;
  padding: 5px 6px;
  min-width: 180px;
  outline: none;
}

.find-count-label {
  font-size: 12px;
  color: var(--text-secondary);
  padding: 0 4px;
  font-family: var(--font-mono);
  white-space: nowrap;
}

/* ----------------------------------------------------
   Feedback & Conflict Alerts
   ---------------------------------------------------- */
.alert-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  font-size: 13px;
  font-weight: 500;
  flex-shrink: 0;
  gap: 12px;
  animation: slideDown 0.2s ease-out;
}

.alert-banner.hidden {
  display: none;
}

.alert-conflict {
  background-color: #451a03;
  color: #fde68a;
  border-bottom: 1px solid #78350f;
}

.alert-error {
  background-color: #450a0a;
  color: #fca5a5;
  border-bottom: 1px solid #7f1d1d;
}

.alert-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ----------------------------------------------------
   Workspace Area (Editor + History Split)
   ---------------------------------------------------- */
.workspace-area {
  display: flex;
  flex: 1;
  min-height: 0;
  position: relative;
  overflow: hidden;
}

/* ----------------------------------------------------
   Custom DOM Editor Root
   ---------------------------------------------------- */
.patchpad-editor-root {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  position: relative;
  outline: none;
  background-color: var(--editor-bg);
}

.patchpad-editor-root.focused {
  /* subtly highlight active border if desired */
}

.patchpad-editor-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  position: relative;
  overflow: hidden;
}

/* Gutter */
.patchpad-gutter {
  width: 58px;
  flex-shrink: 0;
  background-color: var(--editor-gutter-bg);
  border-right: 1px solid var(--border-color);
  user-select: none;
  overflow: hidden;
  position: relative;
}

.patchpad-gutter-content {
  position: relative;
  width: 100%;
}

.patchpad-gutter-line {
  position: absolute;
  left: 0;
  right: 0;
  padding-right: 12px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--editor-gutter-text);
  line-height: 24px;
  cursor: pointer;
}

.patchpad-gutter-line:hover {
  color: var(--text-primary);
  background-color: rgba(255, 255, 255, 0.05);
}

.patchpad-gutter-line.active {
  color: var(--editor-gutter-active);
  font-weight: 600;
}

/* Scroll View & Canvas/Layers */
.patchpad-scroll-view {
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  position: relative;
  cursor: text;
}

.patchpad-scroll-phantom {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
}

.patchpad-view-content {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
}

/* Layers */
.patchpad-selection-layer,
.patchpad-find-layer,
.patchpad-lines-layer,
.patchpad-carets-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.patchpad-selection-rect {
  position: absolute;
  background-color: var(--editor-selection);
  border-radius: 2px;
}

.patchpad-find-match {
  position: absolute;
  background-color: var(--editor-find-match);
  border-bottom: 2px solid #eab308;
}

.patchpad-find-match.active-match {
  background-color: var(--editor-find-active);
  border-bottom: 2px solid #f97316;
}

.patchpad-line {
  position: absolute;
  left: 10px;
  right: 0;
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 24px;
  color: var(--editor-text);
  white-space: pre;
  tab-size: 2;
}

.patchpad-caret {
  position: absolute;
  width: 2px;
  margin-left: 10px;
  background-color: var(--editor-caret);
  opacity: 0;
  transition: opacity 0.05s ease;
}

.patchpad-caret.primary {
  background-color: var(--editor-caret);
}

.patchpad-caret.secondary {
  background-color: var(--editor-caret-sec);
}

.patchpad-caret.visible {
  opacity: 1;
}

/* Hidden Font Ruler */
.patchpad-font-ruler {
  position: absolute;
  top: -9999px;
  left: -9999px;
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 24px;
  visibility: hidden;
  white-space: pre;
}

/* ----------------------------------------------------
   Revision History Sidebar Drawer
   ---------------------------------------------------- */
.history-drawer {
  width: 360px;
  flex-shrink: 0;
  background-color: var(--bg-panel);
  border-left: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: width 0.2s ease;
}

.history-drawer.hidden {
  display: none;
}

.history-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
  background-color: #141f33;
}

.history-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 6px;
}

.history-list {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.history-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color 0.15s ease;
}

.history-card.current {
  border-color: var(--accent-primary);
  background-color: #1e3a5f;
}

.history-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.history-rev-tag {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 13px;
  color: var(--accent-primary);
}

.history-card.current .history-rev-tag {
  color: #38bdf8;
}

.history-timestamp {
  font-size: 11px;
  color: var(--text-secondary);
}

.history-card-meta {
  font-size: 12px;
  color: var(--text-secondary);
}

.history-card-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

/* ----------------------------------------------------
   Modal Dialogs (Preview & Conflict)
   ---------------------------------------------------- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(2px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;
}

.modal-overlay.hidden {
  display: none;
}

.modal-window {
  background-color: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  width: 900px;
  max-width: 95vw;
  max-height: 85vh;
  overflow: hidden;
  animation: modalPop 0.15s ease-out;
}

.modal-window.modal-conflict {
  width: 580px;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  border-bottom: 1px solid var(--border-color);
  background-color: #141f33;
}

.modal-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
}

.modal-body {
  padding: 18px 20px;
  overflow-y: auto;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.preview-code-box {
  background-color: var(--editor-bg);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 12px;
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.6;
  color: var(--editor-text);
  white-space: pre;
  overflow: auto;
